import json,html,re,unicodedata
from pathlib import Path
from xml.sax.saxutils import escape
root=Path(__file__).resolve().parents[1]; out=root/'docs'; stories=json.loads((root/'source/collection.json').read_text(encoding='utf8'))
descriptions_path=root/'source/image-descriptions.json'
descriptions=json.loads(descriptions_path.read_text(encoding='utf8')) if descriptions_path.exists() else {}
