def e(s):return html.escape(str(s),quote=True)
def href(s):return 'relatos/'+s['id']+'.html'
def name(s):
 if s['title'].startswith('CARTA A'):return 'Carta a la médica Dña. Remedios Sanitas'
 if s['title'].startswith('CARTA 2'):return 'Carta 2 (a la directora del periódico)'
 if s['title'].startswith('LUZ'):return 'Luz matinal'
 return s['title']
def head(title,desc,path='',prefix=''):
 return f'''<!doctype html><html lang="es" data-font="large"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#193e37"><title>{e(title)} · Fernando Nieto Nieto</title><meta name="description" content="{e(desc)}"><meta name="robots" content="index, follow"><link rel="canonical" href="{base+path}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:locale" content="es_ES"><meta property="og:url" content="{base+path}"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}styles.css?v=20261003-audio1"><script src="{prefix}audio-player.js?v=20261003-audio1" defer></script><script src="{prefix}app.js?v=20261003-audio1" defer></script></head>'''
def header(prefix='',reader=False):
 return f'''<a class="skip" href="#contenido">Saltar al contenido</a><header class="site-header"><a class="wordmark" href="{prefix}index.html" aria-label="Las palabras de Fernando, inicio"><span class="monogram" aria-hidden="true">fn.</span><span>Las palabras<br><strong>de Fernando</strong></span></a><nav aria-label="Navegación principal"><a class="nav-library" href="{prefix}index.html#coleccion">{'Todos los textos' if reader else 'La colección'}</a>{'' if reader else '<a class="nav-workshop" href="#taller">El taller</a>'}<button class="font-toggle js-only" data-settings aria-controls="reading-settings" aria-expanded="false"><span aria-hidden="true">A<span class="bigger-a">A</span></span> <span>Letra y lectura</span></button></nav></header>'''
def settings():return '''<dialog id="reading-settings" class="settings" aria-labelledby="settings-title"><div><h2 id="settings-title">A tu gusto, a tu ritmo</h2><button data-close-settings aria-label="Cerrar opciones de lectura">Cerrar ×</button></div><fieldset><legend>Tamaño de letra</legend><div class="setting-choices"><button data-font="normal" aria-pressed="false">Normal</button><button data-font="large" aria-pressed="true">Grande</button><button data-font="extra" aria-pressed="false">Muy grande</button></div></fieldset><fieldset><legend>Color de la página</legend><div class="setting-choices"><button data-theme="paper" aria-pressed="true">Papel</button><button data-theme="contrast" aria-pressed="false">Alto contraste</button><button data-theme="night" aria-pressed="false">Noche</button></div></fieldset><p>Tu elección se guarda en este dispositivo.</p></dialog>'''
def footer(prefix=''):return f'''<footer class="site-footer"><a class="wordmark" href="{prefix}index.html"><span class="monogram" aria-hidden="true">fn.</span><span>Las palabras<br><strong>de Fernando</strong></span></a><p>Fernando Nieto Nieto<br><span>Casa de las Conchas · Salamanca · Curso 2025–2026</span></p><a href="{prefix}coleccion-original.pdf" download>Descargar el libro en PDF <span class="small">(2,4 MB)</span></a><p class="footer-note">Una colección para leer y compartir. Textos e imágenes de la edición original.<br>Sin anuncios ni seguimiento. Los ajustes de lectura se guardan solo en tu dispositivo.<br><span class="site-credit">Web creada por Fernando Nieto Lobato.</span></p></footer>'''
def modal():return '''<dialog id="image-dialog" class="image-dialog" aria-label="Ilustración ampliada"><div class="image-bar"><strong>Ilustración del libro</strong><div><button id="zoom-out" aria-label="Reducir ilustración">−</button><button id="zoom-in" aria-label="Ampliar ilustración">+</button><button id="close-image">Cerrar ×</button></div></div><div class="image-scroll"><img id="large-image" alt=""></div><p id="image-help">Usa + para ampliar y desplaza la imagen con el dedo.</p></dialog>'''
def card(s):
 image=f'<img src="{s["images"][0]["src"]}" alt="" loading="lazy" width="{s["images"][0]["width"]}" height="{s["images"][0]["height"]}">' if s['images'] else f'<span class="letter-art" aria-hidden="true">{"Querida…" if s["category"]=="Cartas" else "Luz"}</span>'
 excerpt=' '.join(s['paragraphs'][0]['text'].split());excerpt=excerpt[:145].rsplit(' ',1)[0]+'…' if len(excerpt)>145 else excerpt
 return f'''<article class="story-card" id="texto-{e(s['id'])}" data-category="{e(s['category'])}" data-search="{e(name(s)+' '+s['category']+' '+ ' '.join(p['text'] for p in s['paragraphs']))}"><a href="{href(s)}" class="card-link"><div class="card-image {'typographic' if not s['images'] else ''}">{image}<span class="card-number">{s['number']:02}</span></div><div class="card-copy"><p class="eyebrow">{e(s['category'])} <span>· {s['minutes']} min</span></p><h3>{e(name(s))}</h3><p class="excerpt">{e(excerpt)}</p><span class="read-label">Leer el texto <span aria-hidden="true">＋</span></span></div></a></article>'''
index=head('Las palabras de Fernando','Relatos, recuerdos y poemas de Fernando Nieto Nieto. Taller de Escritura Creativa de la Casa de las Conchas, Salamanca. Curso 2025–2026.')+'''<body data-page="home" data-font="large" data-theme="paper">'''+header()+settings()+f'''<main id="contenido"><section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="tiny-line"></span> RELATOS · POEMAS · RECUERDOS</p><h1>Fernando<br><em>Nieto Nieto</em></h1><p class="hero-description">Recopilación de relatos del curso 2025–2026 del Taller de Escritura de la Casa de las Conchas, impartido por Raúl Vacas.</p><div class="hero-actions"><a class="button primary" href="#coleccion">Elegir un relato</a><button class="button secondary js-only" data-random>Leer un relato al azar</button></div><a id="continue-reading" class="continue-reading" hidden></a><p class="hero-meta">24 textos y un prólogo · Para leer sin prisa</p></div><div class="hero-art"><span class="art-orbit" aria-hidden="true"></span><div class="book"><img src="assets/pagina-01-1.webp" width="601" height="601" alt="Portada original de la colección: Fernando escribiendo, rodeado de recuerdos e historias" fetchpriority="high"></div><div class="edition-stamp"><span>SALAMANCA</span><strong>2025<br>2026</strong><span>EL TALLER</span></div><span class="art-caption">Cada página, una nueva compañía.</span></div></section><section class="prologue-intro" aria-labelledby="prologue-title"><div><p class="eyebrow">EL PRÓLOGO</p><h2 id="prologue-title">Nunca es tarde para escribir.</h2><p class="prologue-credit">Por Juan José Nieto Lobato.</p></div><a class="button primary" href="relatos/prologo.html">Leer el prólogo</a></section><section id="coleccion" class="collection"><div class="section-heading"><div><p class="eyebrow">LA COLECCIÓN</p><h2>¿Qué te apetece leer?</h2></div><p>Elige una historia.<br>El resto puede esperar.</p></div><div class="catalog-tools js-only"><div class="view-switch" role="group" aria-label="Vista de la colección"><button data-view="compact" aria-pressed="false">Índice rápido</button><button data-view="cards" aria-pressed="true">Ver ilustraciones</button></div><div class="filters" role="group" aria-label="Elegir tipo de texto">{''.join(f'<button data-filter="{e(t)}" aria-pressed="{str(i==0).lower()}">{t}</button>' for i,t in enumerate(['Todos','Memoria y raíces','Historias','Poesía y juegos','Cartas']))}</div><label class="search-label"><span>Buscar en los textos</span><input type="search" id="search" placeholder="Un título, una palabra…" autocomplete="off"></label></div><p id="result-count" class="result-count" aria-live="polite">24 textos para descubrir</p><div class="story-grid">{''.join(card(s) for s in stories[1:])}</div><div id="no-results" class="empty-state" hidden><h3>No hay textos con esa búsqueda</h3><p>Prueba otra palabra o vuelve a ver la colección completa.</p><button id="reset-search" class="button primary">Ver todos los textos</button></div></section><section id="taller" class="workshop"><div class="workshop-image"><img src="assets/pagina-02-1.webp" width="600" height="225" alt="Taller de Escritura Creativa de la Casa de las Conchas" loading="lazy"></div><div><p class="eyebrow">EL LUGAR DONDE NACIERON</p><h2>Un taller.<br>Mil formas de mirar.</h2><p>Esta colección reúne los textos de Fernando Nieto Nieto para el Taller de Escritura Creativa de la Casa de las Conchas, en Salamanca, impartido por Raúl Vacas durante el curso 2025–2026.</p><p>Relatos, poemas, cartas y juegos con las palabras. La edición original se recopiló el 26 de junio de 2026.</p><a class="text-link" href="coleccion-original.pdf" download>Guardar el libro original en PDF (2,4 MB)</a></div></section></main>'''+footer()+'''<script type="application/ld+json">'''+json.dumps({'@context':'https://schema.org','@type':'Book','name':'Colección de textos para el Taller de Escritura Creativa Casa de las Conchas, Salamanca','author':{'@type':'Person','name':'Fernando Nieto Nieto'},'inLanguage':'es','datePublished':'2026-06-26','url':base},ensure_ascii=False)+'''</script></body></html>'''
(out/'index.html').write_text(index,encoding='utf8')
(out/'relatos').mkdir(exist_ok=True)
for i,s in enumerate(stories):
 image_html=[]
 for im in s['images']:
  description=descriptions.get(im['src'],{})
  alt=description.get('alt','Ilustración original de '+name(s))
  accessible=description.get('description','')
  explanation='<details class="image-description"><summary>Descripción de la ilustración</summary><div>'+e(accessible)+'</div></details>' if accessible else ''
  quality='<span class="image-quality">La imagen original es pequeña; al ampliarla puede perder nitidez.</span>' if im['width']<400 else ''
  caption=next((p['text'] for p in s['paragraphs'] if p['type']=='caption'),'Ilustración de la edición original.')
  image_html.append(f'''<figure class="story-figure"><a href="../{im['src']}" class="zoom-image" data-image="../{im['src']}" aria-label="Ampliar ilustración de {e(name(s))}"><img src="../{im['src']}" width="{im['width']}" height="{im['height']}" alt="{e(alt)}" loading="lazy"><span class="image-hint">Ampliar ilustración ＋</span></a><figcaption>{e(caption)}{quality}</figcaption>{explanation}</figure>''')
 paragraphs=[]
 for p in s['paragraphs']:
  if p['type']=='caption':continue
  tag='h2' if p['type']=='h2' else 'p'; cls=' class="verse"' if p['type']=='verse' else ''
  paragraphs.append(f'<{tag}{cls}>{e(p["text"])}</{tag}>')
 # Haikus retain the association of each three-line poem with its own image.
 if s['title']=='Haikus':
  content='';verses=[p['text'] for p in s['paragraphs']]
  for n in range(3):content+='<div class="haiku"><p class="verse">'+e('\n'.join(verses[n*3:n*3+3]))+'</p>'+image_html[n]+'</div>'
 else:content=''.join(paragraphs)
 art='' if s['title']=='Haikus' else ''.join(image_html)
 prev=stories[i-1] if i>0 else None; nxt=stories[i+1] if i+1<len(stories) else None
 nav='<nav class="story-navigation" aria-label="Navegar entre textos">'
 if prev:nav+=f'<a href="{prev["id"]}.html"><span>Texto anterior</span><strong>{e(name(prev))}</strong></a>'
 else:nav+='<a href="../index.html#coleccion"><span>Volver a empezar</span><strong>Ver la colección</strong></a>'
 if nxt:nav+=f'<a href="{nxt["id"]}.html"><span>Siguiente texto</span><strong>{e(name(nxt))}</strong></a>'
 else:nav+='<a href="../index.html#coleccion"><span>Hay más por descubrir</span><strong>Volver a la colección</strong></a>'
 nav+='</nav>'
 desc=' '.join(s['paragraphs'][0]['text'].split())[:160]
 doc=head(name(s),desc,href(s),'../')+f'''<body data-page="reader" data-story="{e(s['id'])}" data-title="{e(name(s))}" data-font="large" data-theme="paper">'''+header('../',True)+settings()+f'''<div class="reading-progress" aria-hidden="true"><span></span></div><main id="contenido"><div class="reader-heading"><a class="back-link" href="../index.html#coleccion">Volver a la colección</a><p class="eyebrow">{e(s['category'])} · {'PRÓLOGO' if i==0 else 'TEXTO '+str(i).zfill(2)} · {s['minutes']} MIN DE LECTURA</p><h1>{e(name(s))}</h1><p class="byline">{e(s['author'])}</p>{'<p class="original-subtitle">Lipograma sin “e”</p>' if s['title'].startswith('LUZ') else ''}</div><div class="reader-share js-only"><button id="share-story">Compartir este texto</button></div><details class="audio-options js-only"><summary>Voz y velocidad</summary><div class="audio-options-body"><div class="audio-choices"><label for="narration-voice">Voz<select id="narration-voice"><option value="alvaro">Álvaro · masculina</option><option value="elvira">Elvira · femenina</option></select></label><label for="narration-speed">Velocidad<select id="narration-speed"><option value="0.85">Más despacio</option><option value="1" selected>Normal</option><option value="1.15">Un poco más rápido</option></select></label></div><audio id="story-audio" controls preload="none" aria-label="Escuchar este texto"></audio><p class="audio-note">Voces generadas con inteligencia artificial, en español de España. Al cambiar de voz, el relato empieza de nuevo.</p><p id="audio-error" role="status" hidden></p></div></details><nav class="reader-tools js-only" aria-label="Controles de lectura"><a href="../index.html#coleccion">Índice</a><button data-settings aria-controls="reading-settings" aria-expanded="false">Letra</button><button id="listen" hidden>Escuchar</button><button id="stop-listening" hidden>Detener voz</button></nav><p id="reader-status" class="reader-status" role="status"></p><article id="story-text" class="story-text" aria-label="{e(name(s))}">{content}</article><section class="story-art" aria-label="Ilustraciones del texto">{art}</section><div class="story-end"><span aria-hidden="true">✦</span><p>{'Fin del prólogo' if i==0 else 'Fin del texto'}</p><a href="../coleccion-original.pdf#page={s['pdfStart']}" target="_blank" rel="noopener">Ver en el libro original <span class="small">(PDF, nueva pestaña)</span></a></div>{nav}<section class="reader-bottom"><button class="button secondary js-only" data-random>Descubrir otro texto</button><a class="text-link" href="../index.html#coleccion">Ver toda la colección</a></section></main>'''+footer('../')+modal()+'''</body></html>'''
 (out/'relatos'/f'{s["id"]}.html').write_text(doc,encoding='utf8')
(out/'assets/catalog.json').write_text(json.dumps([{'id':s['id'],'title':name(s),'href':href(s)} for s in stories[1:]],ensure_ascii=False),encoding='utf8')
(out/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#193e37"/><text x="9" y="45" font-family="Georgia,serif" font-size="40" font-weight="bold" fill="#f8f4e8">fn.</text></svg>',encoding='utf8')
(out/'.nojekyll').touch()
(out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+base+'sitemap.xml\n',encoding='utf8')
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+escape(base+p)+'</loc></url>' for p in ['']+[href(s) for s in stories])+'</urlset>',encoding='utf8')
(out/'404.html').write_text(head('Página no encontrada','Volver a la colección de Fernando Nieto Nieto.',prefix=base)+'<body><main class="not-found"><p class="eyebrow">ESTA PÁGINA SE HA TRASPAPELADO</p><h1>La historia sigue por aquí.</h1><a class="button primary" href="'+base+'">Volver a la colección</a></main></body></html>',encoding='utf8')
print('Built home +',len(stories),'reading pages')
